/* Rise 28px and fade in over the first 220px of scroll after the element's top enters the
   window (a fixed distance, so things already in the first screen are in place at load).
   Each step starts 40px later. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .storeyarchitecture-rise {
      animation: storeyarchitecture-rise-in linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--storeyarchitecture-rise-step, 0) * 40px) entry calc(220px + var(--storeyarchitecture-rise-step, 0) * 40px);
    }
  }
}

@keyframes storeyarchitecture-rise-in {
  from {
    opacity: 0;
    transform: translateY(28px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./storeyarchitecture-rise.css";

export interface StoreyarchitectureRiseProps {
  children?: ReactNode;
  /** the element to render (div by default) */
  as?: ElementType;
  /** position in a staggered row: 0, 1, 2… each arrives 40px of scroll later */
  step?: number;
  className?: string;
}

export function StoreyarchitectureRise({ children, as: Tag = "div", step = 0, className }: StoreyarchitectureRiseProps) {
  return (
    <Tag className={cn("storeyarchitecture-rise", className)} style={{ "--storeyarchitecture-rise-step": step } as CSSProperties}>
      {children}
    </Tag>
  );
}
